pub fn first_even_odd_indices(lst: Vec<i32>) -> (usize, usize) {
    // Find the first index of an even number.
    let first_even = lst
        .iter()
        .position(|&x| x % 2 == 0)
        .expect("The list must contain at least one even number");

    // Find the first index of an odd number.
    let first_odd = lst
        .iter()
        .position(|&x| x % 2 != 0)
        .expect("The list must contain at least one odd number");

    (first_even, first_odd)
}

